page_settings.custom_css:
/* Home V13 · comportamiento común de las tarjetas */
.mk-foto { position: relative; overflow: hidden; }
a.e-con { text-decoration: none; }
/* Hero: cada diapositiva ocupa todo el ancho de la pantalla */
body:not(.elementor-editor-active) .mk-slider { grid-template-columns: minmax(0, 1fr); justify-content: stretch !important; }
a.e-con:focus-visible { outline: 3px solid #6B5BD6; outline-offset: 3px; }
@media (prefers-reduced-motion: reduce) { a.e-con, a.e-con .elementor-icon { transition: none !important; } }

